from sklearn.metrics._regression import _weighted_percentile, _average
import numpy as np


def weekly_kpi(actual, forecast, demand_weight):
    """Demand-weighted median absolute forecast error for one week (lower is better)."""
    errors = np.abs(np.asarray(forecast) - np.asarray(actual))
    if demand_weight is None:
        weights = np.ones_like(errors)
    else:
        weights = np.asarray(demand_weight)

    output_errors = _weighted_percentile(errors, sample_weight=weights, average=False)
    return float(_average(output_errors, weights=None))

